// SOURCE of the Vercel function api/reports.mjs (generated by `npm run build:api -w @phc/reports`; a test fails if the two differ).
// The one server function for reports: build, send and send-a-test. It acts as the signed-in manager (their own Supabase session, so
// row-level security applies) and never holds a service key. All logic lives in packages/reports (tested); this file only wires in the
// real Supabase and Gmail. Settings (Vercel, never in the repo): REPORT_FROM, REPORT_TIMEZONE, REPORT_TRANSPORT, GMAIL_CLIENT_ID,
// GMAIL_CLIENT_SECRET, GMAIL_REFRESH_TOKEN, PHC_EMAIL_DOMAIN (the company email domain colleagues must be on). The Supabase address and publishable key are read from the same settings the app build uses.
import { createClient } from "@supabase/supabase-js";
import { getTransport } from "./server/transport";
import { handleReportsRequest } from "./server/handler";
import { supabaseDb, supabaseStorage } from "./server/supabaseAdapters";

interface Req { method?: string; headers: Record<string, string | string[] | undefined>; body?: unknown }
interface Res { status(code: number): Res; setHeader(k: string, v: string): Res; json(body: unknown): void }

export default async function handler(req: Req, res: Res): Promise<void> {
  const env = process.env;
  const url = env.SUPABASE_URL || env.VITE_SUPABASE_URL;
  const key = env.SUPABASE_PUBLISHABLE_KEY || env.VITE_SUPABASE_PUBLISHABLE_KEY;
  res.setHeader("Cache-Control", "no-store");
  if (!url || !key) { res.status(500).json({ error: "not_configured", message: "The server is missing the Supabase address or key." }); return; }
  const auth = Array.isArray(req.headers.authorization) ? req.headers.authorization[0] : req.headers.authorization;

  const out = await handleReportsRequest({ method: req.method ?? "", authorization: auth, body: req.body }, {
    getUser: async (token) => {
      const { data, error } = await createClient(url, key, { auth: { persistSession: false } }).auth.getUser(token);
      return error || !data.user ? null : { id: data.user.id, email: data.user.email ?? null };
    },
    makeDeps: (token) => {
      const sb = createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false }, global: { headers: { Authorization: `Bearer ${token}` } } });
      return { db: supabaseDb(sb), storage: supabaseStorage(sb) };
    },
    transport: () => getTransport(env),
    env: { ...(env.REPORT_FROM ? { REPORT_FROM: env.REPORT_FROM } : {}), ...(env.REPORT_TIMEZONE ? { REPORT_TIMEZONE: env.REPORT_TIMEZONE } : {}), ...(env.PHC_EMAIL_DOMAIN ? { PHC_EMAIL_DOMAIN: env.PHC_EMAIL_DOMAIN } : {}) },
  });
  res.status(out.status).json(out.json);
}

export const config = { maxDuration: 60 };
